# focus on net/ethernet + wireless + staging + net/
files += [f for f in subprocess.run(['grep','-rln','netif_napi_add','--include=*.c','net/'], capture_output=True, text=True).stdout.split()]

res = []
for f in files:
    try: lines = open(f, errors='ignore').read().split('\n')
    except: continue
    # find poll fn names
    polls = set()
    for l in lines:
        for m in re.finditer(r'netif_napi_add(?:_tx|_weight)?\s*\([^;]*?,\s*([A-Za-z_0-9]+)\s*,', l):
            polls.add(m.group(1))
        for m in re.finditer(r'netif_napi_add(?:_tx|_weight)?\s*\(\s*[^,]+,\s*&?[A-Za-z_0-9>.]+\s*,\s*([A-Za-z_0-9]+)', l):
            polls.add(m.group(1))
    if not polls: continue
    # find each poll def
    for p in polls:
