            if re.search(r'\b'+re.escape(p)+r'\s*\(.*\)\s*$', l) or re.search(r'\b'+re.escape(p)+r'\s*\(', l) and '{' not in l and 'napi_add' not in l and not re.search(r'&\s*'+re.escape(p), l):
